"use client";

import { LayerProvider, Theme } from "@astryxdesign/core";
// Built theme (generated by `npm run build:theme`, see src/lib/astryxTheme.ts
// for the source) — ships as static CSS instead of injecting a <style> tag
// after hydration, which caused a flash-of-unstyled-content on first load.
import { vcScoutTheme } from "../../lib/vc-scout";

export default function AstryxProvider({ children }: { children: React.ReactNode }) {
  return (
    <LayerProvider toast={{ position: "bottomEnd", maxVisible: 3 }}>
      <Theme theme={vcScoutTheme} mode="light">
        {children}
      </Theme>
    </LayerProvider>
  );
}
